discoverUrl:
@js:
(() => {
  const selected = [
    ['sort', values.sort],
    ['filter[country]', values['filter[country]']],
    ['filter[tag]', values['filter[tag]']],
    ['filter[audience]', values['filter[audience]']],
    ['filter[year]', values['filter[year]']],
    ['filter[end]', values['filter[end]']]
  ];
  const query = selected
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`);
  query.push(`page=${page}`);
  return `${host}/comics?${query.join('&')}`;
})()
